<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization-table__box">
      <div class="optimization-option">
        <ul class="optimization-option__box">
          <li class="optimization-option__item">
            <div class="optimization-option__text-box">
              <span class="optimization-option__text">Разделы</span>
              <CustomSelect
                v-model="selectPartition"
                placeholder="Автомобили"
                :options="options"
                @updateSort="chekedSort"
              />
            </div>
            <ButtonUI
              svg="read-log"
              text="Читать лог"
              buttonClass="btn--third"
              @action="router.push('/seo/filters/log')"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Отображение URL</span>
            <AutosTextTemplate placeholder="Отображение URL" />
          </li>
        </ul>
      </div>
      <CustomTable
        :ItemRows="itemRow"
        :headerRows="headerRow"
        :tablePagination="showPagination"
        @slot-clicked="handleButtonClick"
        @item-action="tableAction"
        :currentPage="pagination.currentPage"
        :perPage="pagination.perPage"
        :total="pagination.totalPages"
        @update:currentPage="(val) => handlePageChange(val)"
      >
        <template #slot-end="{ item, emitEvent }">
          <div class="table-box__slot-box">
            <ButtonUI
              svg="edit-svg"
              :buttonClass="'btn--third'"
              @action="emitEvent(item)"
            />
            <div class="table-box__slot-text" @click="emitEvent(item)">
              <span class="table-box__slot-title">Настройки</span>
              <span class="table-box__slot-text" v-if="item?.count?.text">
                {{ item.count.text }}
              </span>
              <span class="table-box__slot-error" v-else>Не уточнено </span>
            </div>
          </div>
        </template>
      </CustomTable>
      <div class="optimization__btn-box" v-if="!showPagination">
        <ButtonUI
          text="Сохранить изменения"
          @action="saveTable"
          :loading="loader"
        />
        <ButtonUI
          text="Сбросить"
          buttonClass="btn--second"
          @action="resetValue"
          :loader="loader"
        />
      </div>
    </div>
    <CustomPopUP
      v-if="isChangeMenu"
      name="Change"
      :data="itemList"
      @closing="resetValue()"
      @submit-action="popUpAction"
    />
  </div>
</template>
<!-- recurring_positions -->
<script setup>
import { ref, onMounted } from 'vue';
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import CustomTable from '@/components/UI/CustomTable.vue';
import { useFilterTable } from '@/store/Table/filterTable.js';
import { useQueryParams } from '@/composables/useQueryParams';

import CustomSelect from '@/components/UI/CustomSelect';

import ButtonUI from '@/components/UI/ButtonUI.vue';
import CustomPopUP from '@/components/POPUP/PopUp';
import AutosTextTemplate from '@/components/UI/AutosTextTemplate.vue';
import router from '@/router';

import { getFilterOption, updateFilterTable } from '@/services/apiClient.js';
import { isEqual, cloneDeep } from 'lodash';

//
const filterTable = useFilterTable();

const title = ref('Фильтры');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const options = ref(null);
const isChangeMenu = ref(false);
const loader = ref(false);

const headerRow = ref([]);
const oldModel = ref([]);
const itemRow = ref([]);
const newRow = ref([]);

const areEqual = ref(false);
const showPagination = ref(true);
const itemList = ref({
  changeItems: null,
  newUrl: 'url',
  oldUrl: 'oldURl',
  postion: 3,
  data: null,
});

const pagination = ref({
  currentPage: 1,
  perPage: 1,
  totalPages: 1,
});

const selectPartition = ref({
  name: 'Автомобили',
  code: '1',
});

// const getFilterParameter = async () => {
//   const data = await getFilterParameterView();
// };
const {
  queryParams,
  loadQueryParamsFromRoute,
  updateQueryParams,
  buildQueryString,
} = useQueryParams();

const handleButtonClick = (item) => {
  router.push({
    name: 'FilterEditPage',
    query: {
      section_id: item.filter.category.id,
      filter_id: item.titleUrl.id,
    },
  });
};

const handlePageChange = (newPage) => {
  pagination.value.currentPage = newPage;
  queryParams.value.page = newPage;
  updateQueryParams();
  getItemRow();
};
const chekedSort = async (option) => {
  queryParams.value.section_id = option;
  updateQueryParams();
  await filterTable.getFilterItem(buildQueryString(queryParams.value));
  itemRow.value = filterTable.getItemRow;
};
const popUpAction = async (item) => {
  const json = ref({});

  json.value.ids = item.items.map((el, index) => ({
    title: el.title,
    section_id: +el.section.id,
    id: +el.id,
    is_active: el.is_active,
    view_id: el.id,
    is_cnc: el.is_cnc ? 1 : 0,
    is_multiplier: el.is_multiplier,
    is_no_index: el.is_no_index,
    title_url: el?.title_url,
    is_url: el.is_url,
    number_in_filter: +el.number_in_filter,
    number_in_url: item.data[index].newPosition.value.code,
  }));
  updateQueryParams();
  getItemRow();
  json.value.is_finished = 0;
  const data = await updateFilterTable(json.value);
  if (data) {
    newRow.value = [];
    oldModel.value = cloneDeep(itemRow.value);
    areEqual.value = true;
    showPagination.value = true;
    isChangeMenu.value = false;
  }
};
const getItemRow = async () => {
  if (!queryParams.value.section_id) {
    queryParams.value.section_id = 1;
  }

  updateQueryParams();
  await filterTable.getFilterItem(buildQueryString(queryParams.value));
  pagination.value = filterTable.getPagination;
  itemRow.value = filterTable.getItemRow;
  oldModel.value = cloneDeep(filterTable.getItemRow);
};
const getHeaderRow = () => {
  headerRow.value = filterTable.getHeaderRow;
};

const tableAction = async () => {
  newRow.value = [];
  await new Promise((resolve) => setTimeout(resolve, 50));
  getChangedEntities(itemRow.value, oldModel.value);
  areEqual.value = newRow.value.length === 0;
  showPagination.value = areEqual.value;
};

const getChangedEntities = (currentItems, oldItems) => {
  newRow.value = [];
  for (let i = 0; i < currentItems.length; i++) {
    const currentItem = currentItems[i];
    const oldItem = oldItems[i];

    if (!isEqual(currentItem, oldItem)) {
      newRow.value.push(currentItem);
    }
  }
};

const convertBack = (items) => {
  return items.map((item) => ({
    title: item?.titleUrl.title,
    section_id: +item.titleUrl.sectionId,
    id: +item.titleUrl.id,
    is_active: item.act.value ? 1 : 0,
    view_id: +item.view.code,
    is_cnc: item.CNC.value,
    is_multiplier: item.multiple.value ? 1 : 0,
    is_no_index: item.noindex.value ? 1 : 0,
    title_url: item?.titleUrl.value,
    is_url: item.CNC?.value ? 1 : 0,
    number_in_filter: +item.positionInUrl?.value,
    number_in_url: +item.position?.value,
  }));
};
const saveTable = async () => {
  const json = ref({});
  json.value.ids = convertBack(newRow.value);
  json.value.is_finished = 0;
  const data = await updateFilterTable(json.value);

  if (data.success) {
    newRow.value = [];
    oldModel.value = cloneDeep(itemRow.value);
    areEqual.value = true;
    showPagination.value = true;
  } else {
    isChangeMenu.value = true;
    itemList.value.newUrl = data.new_url;
    itemList.value.oldUrl = data.old_url;
    itemList.value.message = data.message;
    itemList.value.error = data.error;
    itemList.value.items = data.recurring_positions;
    itemList.value.data = data.recurring_positions.map((el) => {
      return {
        filter: {
          value: el.title,
          type: 'text',
        },
        oldPosition: {
          value: el.number_in_url,
          type: 'text',
          contenteditable: false,
        },
        newPosition: {
          value: {
            name: el.number_in_url,
            code: el.number_in_url,
          },
          type: 'select',
          options: data.available_url_numbers.map((el) => {
            return {
              name: el,
              code: el,
            };
          }),
          contenteditable: false,
        },
      };
    });
  }
};
const resetValue = () => {
  isChangeMenu.value = false;
  itemRow.value = cloneDeep(oldModel.value);
  tableAction();
};
const getParametrQRL = async () => {
  loadQueryParamsFromRoute();

  const data = await getFilterOption();

  options.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));
  if (queryParams.value.section_id) {
    selectPartition.value = options.value.find(
      (el) => el.code == queryParams.value.section_id
    );
  }
};
onMounted(() => {
  loadQueryParamsFromRoute();
  getItemRow();
  getHeaderRow();
  getParametrQRL();
});
//  getFilterParameter();
</script>

<style scoped lang="scss">
.optimization {
  display: flex;
  flex-direction: column;
  height: calc(100vh - 200px);
  padding: 10px;
  @media (max-width: 1024px) {
    justify-content: space-between;
    height: calc(100vh - 60px);
    margin-top: 65px;
    padding: 20px;
  }

  &-table__box {
    min-height: calc(100vh - 90px);
    height: calc(100vh - 200px);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  &-option {
    display: flex;
    justify-content: space-around;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 24px 0;
    padding: 12px 24px;

    &__box {
      display: flex;
      flex-direction: column;
      width: 100%;
    }

    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;

      &:first-child {
        justify-content: space-between;
      }
    }

    &__text-box {
      display: flex;
    }

    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
  }
  &__btn-box {
    display: flex;
    align-items: center;
    gap: 24px;
  }
}

.table-box__slot-box {
  display: flex;
}

.table-box__slot-title {
  color: #3366ff;
}

.table-box__slot-text {
  display: flex;
  font-size: 10px;
  flex-direction: column;
}

.table-box__slot-error {
  color: #ff5959;
  font-size: 10px;
}
</style>
