import { defineStore } from 'pinia';
import { getParameterFilterSection } from '@/services/apiClient.js';

export const useFilterTable = defineStore('useFilterTable', {
  state: () => ({
    itemRow: [],

    headerRows: [
      {
        name: 'Акт',
        width: '75px',
        helper: false,
      },
      {
        name: 'Фильтр',
        helper: {
          title: 'Фильтр',
          text: 'Название (заголовок) параметра фильтрации на странице сайта',
        },
        width: '150px',
      },
      {
        name: 'Вид',
        helper: false,
        width: '110px',
      },
      {
        name: 'Множ',
        helper: {
          title: 'Множественное значение',
          text: 'Установленная в чекбокс галочка позволяет одновременно использовать несколько значений при фильтрации объявлений',
        },
        width: '70px',
      },
      {
        name: 'Noindex',
        helper: false,
        width: '75px',
      },
      {
        name: 'Позиция в фильтре',
        helper: false,
        width: '70px',
      },
      {
        name: 'ЧПУ',
        helper: false,
        width: '75px',
      },
      {
        name: 'Заголовок в URL',
        helper: {
          title: 'Заголовок в URL',
          text: 'Данный параметр позволяет использовать короткий, оптимизированый заголовок при формировании ЧПУ',
        },
        width: '150px',
      },
      {
        name: 'Позиция в URL',
        helper: false,
        width: '75px',
      },
      {
        name: 'URL Объяв',
        helper: {
          title: 'URL объявления',
          text: 'Чекбокс определяет, учавстветвует ли фильтр в формировании URL объявления. Параметр недоступен, если ЧПУ фильтра отключено.',
        },
        width: '75px',
      },
      {
        name: 'значение',
        helper: {
          title: 'Значения фильтра',
          text: 'Включают в себя все доступные значения фильтра и их индивидуальные настройки. Пометка “Не уточнено” говорит о том, что значения нуждаются в настройке.',
        },
        width: '150px',
      },
    ],

    pagination: { currentPage: 0, perPage: 0, totalPages: 0 },
  }),

  actions: {
    async getFilterItem(params) {
      const data = await getParameterFilterSection(params);
      this.pagination.currentPage = data.current_page;
      this.pagination.perPage = data.total_page;
      this.pagination.totalPages = data.total_page;
      console.log(data);
      this.data = data;

      this.itemRow = data.data.map((item) => ({
        act: {
          value: !!item.is_active,
          type: 'checkbox',
          contenteditable: false,
          change: false,
        },
        filter: {
          value: item.title || '',
          category: item.section,
          type: 'text',
          contenteditable: false,
        },
        view: {
          value: item.view.title || '',
          type: 'text',
          code: item.view.id,
          contenteditable: false,
        },
        multiple: {
          // Added colon after 'multiple'
          value: !!item.is_multiplier,
          type: 'checkbox',
          contenteditable: false,
        },
        noindex: {
          value: !!item.is_no_index,
          type: 'checkbox',
          contenteditable: false,
        },
        position: {
          value: item.number_in_filter || '',
          type: 'text',
          contenteditable: true,
        },
        CNC: {
          value: !!item.is_cnc,
          type: 'checkbox',
          contenteditable: false,
        },
        titleUrl: {
          value: item.title_url || '',
          type: 'text',
          title: item.title,
          contenteditable: true,
          id: item.id,
          sectionId: item.section.id,
          change: false,
        },
        positionInUrl: {
          value: item.number_in_url || '',
          type: 'text',
          contenteditable: true,
        },
        urlCard: {
          value: !!item.is_url,
          type: 'checkbox',
          contenteditable: false,
          id: 1,
        },
        count: {
          slot: 'end',
          contenteditable: false,
          text: `Изм. ${item.created_at}`,
        },
      }));
    },

    //  siteMapInfoErrorFetch(){
    //  }
  },

  getters: {
    getFilterLog: (state) => state.filterLog,
    getHeaderRow: (state) => state.headerRows,
    getItemRow: (state) => state.itemRow,
    getPagination: (state) => state.pagination,
  },
});
